import{_ as e,o as t,c as r,a2 as n}from"./chunks/framework.DGzjq_gw.js";const u=JSON.parse('{"title":"工程化与场景题","description":"","frontmatter":{},"headers":[],"relativePath":"interview/engineering-questions.md","filePath":"interview/engineering-questions.md","lastUpdated":1792491378000}'),s={name:"interview/engineering-questions.md"};function a(c,o,d,i,l,g){return t(),r("div",null,[...o[0]||(o[0]=[n('<h1 id="工程化与场景题" tabindex="-1">工程化与场景题 <a class="header-anchor" href="#工程化与场景题" aria-label="Permalink to &quot;工程化与场景题&quot;">​</a></h1><p>本页覆盖二面最深的两类题：<strong>工程化问答</strong>（考察工具链与工程规范）与<strong>场景设计题</strong>（考察架构与系统思维）。每题给&quot;答题框架 + 要点&quot;。对应 JD 要求 A4（工程化工具）+ A5（组件库/SDK 建设）+ B2（测试）。</p><blockquote><p>深入阅读：<a href="/frontend-kb-pages/engineering/build-tools">构建工具 Vite/Webpack</a>、<a href="/frontend-kb-pages/engineering/monorepo">Monorepo</a>、<a href="/frontend-kb-pages/engineering/ci-cd">CI/CD</a>、<a href="/frontend-kb-pages/engineering/component-lib">组件库建设</a>、<a href="/frontend-kb-pages/quality/unit-test">单元测试</a>、<a href="/frontend-kb-pages/quality/e2e-test">E2E 测试</a>。</p></blockquote><h2 id="一、工程化问答" tabindex="-1">一、工程化问答 <a class="header-anchor" href="#一、工程化问答" aria-label="Permalink to &quot;一、工程化问答&quot;">​</a></h2><h3 id="q1-vite-与-webpack-的区别" tabindex="-1">Q1. Vite 与 Webpack 的区别？ <a class="header-anchor" href="#q1-vite-与-webpack-的区别" aria-label="Permalink to &quot;Q1. Vite 与 Webpack 的区别？&quot;">​</a></h3><p><strong>要点</strong>：Webpack 是&quot;<strong>先打包再启动</strong>&quot;（bundle-based），启动需构建整个依赖图；Vite 开发环境基于<strong>原生 ESM</strong>，不打包、按需编译（esbuild 预构建依赖），<strong>启动极快</strong>；生产环境 Vite 用 Rollup 打包。</p><p><strong>深度补充</strong>：Vite 的 HMR 精确到模块、随包体增大不明显变慢；Webpack 的 HMR 需重新构建受影响 chunk，大项目会变慢。Vite 生态兼容性曾有 gap（如某些 CJS 插件），现已有 <code>vite-plugin</code> 体系补齐。对应 A4 级要求（9 份 JD）。</p><h3 id="q2-vite-的核心配置与优化有哪些" tabindex="-1">Q2. Vite 的核心配置与优化有哪些？ <a class="header-anchor" href="#q2-vite-的核心配置与优化有哪些" aria-label="Permalink to &quot;Q2. Vite 的核心配置与优化有哪些？&quot;">​</a></h3><p><strong>要点</strong>：<code>resolve.alias</code>（路径别名）、<code>server.proxy</code>（开发代理跨域）、<code>build.rollupOptions.manualChunks</code>（分包）、<code>build.target</code>、<code>optimizeDeps.include/exclude</code>（预构建）、插件（<code>@vitejs/plugin-react</code>、<code>unplugin-auto-import</code>）。</p><p><strong>深度补充</strong>：<code>manualChunks</code> 把 <code>react</code>/<code>vue</code>/<code>echarts</code> 拆成独立 chunk 提升缓存命中；<code>build.chunkSizeWarningLimit</code> 观察包体；<code>vite-plugin-inspect</code> 排查插件问题。生产用 <code>rollup-plugin-visualizer</code> 分析依赖构成。</p><h3 id="q3-webpack-的核心概念与优化手段" tabindex="-1">Q3. Webpack 的核心概念与优化手段？ <a class="header-anchor" href="#q3-webpack-的核心概念与优化手段" aria-label="Permalink to &quot;Q3. Webpack 的核心概念与优化手段？&quot;">​</a></h3><p><strong>要点</strong>：核心是 <code>entry/output/loader/plugin/mode</code>。优化：<code>splitChunks</code> 分包、<code>treeShaking</code>、<code>cache</code>（持久化缓存）、<code>externals</code>（CDN 外置）、<code>thread-loader</code>/<code>esbuild-loader</code> 提速、<code>DllPlugin</code>（历史方案）。</p><p><strong>深度补充</strong>：<code>splitChunks</code> 的 <code>chunks: &#39;all&#39;</code> 会把异步与同步共享模块提取为公共 chunk；<code>runtimeChunk: &#39;single&#39;</code> 稳定长期缓存。<code>resolve.extensions</code> 精简、<code>module.noParse</code> 可减少解析。</p><h3 id="q4-pnpm-与-npm-yarn-的区别-为什么要用-pnpm" tabindex="-1">Q4. pnpm 与 npm/yarn 的区别？为什么要用 pnpm？ <a class="header-anchor" href="#q4-pnpm-与-npm-yarn-的区别-为什么要用-pnpm" aria-label="Permalink to &quot;Q4. pnpm 与 npm/yarn 的区别？为什么要用 pnpm？&quot;">​</a></h3><p><strong>要点</strong>：pnpm 用<strong>内容寻址存储 + 硬链接</strong>，全局只存一份，项目通过硬链接引用；配合<strong>符号链接</strong>构建严格 node_modules 结构，避免幽灵依赖。npm/yarn 是&quot;打平&quot;或多次拷贝。</p><p><strong>深度补充</strong>：pnpm 的严格结构让&quot;未在 <code>package.json</code> 声明的依赖无法被直接 import&quot;（杜绝幽灵依赖），但某些老库会因找不到打平的依赖而报错，可用 <code>shamefully-hoist</code> 兼容。速度与磁盘占用优势明显。</p><h3 id="q5-pnpm-workspace-与-monorepo-的组织方式" tabindex="-1">Q5. pnpm workspace 与 Monorepo 的组织方式？ <a class="header-anchor" href="#q5-pnpm-workspace-与-monorepo-的组织方式" aria-label="Permalink to &quot;Q5. pnpm workspace 与 Monorepo 的组织方式？&quot;">​</a></h3><p><strong>要点</strong>：<code>pnpm-workspace.yaml</code> 声明 <code>packages/*</code>；各包通过 <code>workspace:*</code> 协议互相引用（本地软链，免发布）；根 <code>package.json</code> 统一脚本；用 <code>filter</code> 只跑某包的脚本（<code>pnpm --filter pkg build</code>）。</p><p><strong>深度补充</strong>：Monorepo 的价值是&quot;统一依赖与配置、原子提交、跨包复用&quot;。代价是需要处理<strong>构建顺序</strong>与<strong>版本一致性</strong>。组件库场景（命中 7 份 JD）常把 <code>packages/components</code>、<code>packages/tokens</code>、<code>apps/docs</code> 放在同一仓库。</p><h3 id="q6-turborepo-与-changesets-分别解决什么" tabindex="-1">Q6. Turborepo 与 Changesets 分别解决什么？ <a class="header-anchor" href="#q6-turborepo-与-changesets-分别解决什么" aria-label="Permalink to &quot;Q6. Turborepo 与 Changesets 分别解决什么？&quot;">​</a></h3><p><strong>要点</strong>：<strong>Turborepo</strong> 做<strong>任务编排与缓存</strong>——按依赖图并行/串行跑 <code>build/lint/test</code>，命中缓存则跳过；<strong>Changesets</strong> 做<strong>版本与发布管理</strong>——记录变更、自动升版本号、生成 CHANGELOG、发布 npm。</p><p><strong>深度补充</strong>：Turborepo 的 <code>pipeline</code> 声明任务依赖（如 <code>build</code> 依赖 <code>^build</code>），支持远程缓存（CI 提速）。Changesets 在 PR 中让作者写一个变更文件，合并后由 CI 统一版本与发布——是组件库（多包）发布的标准组合。</p><h3 id="q7-eslint-与-prettier、stylelint-如何分工与协作" tabindex="-1">Q7. ESLint 与 Prettier、Stylelint 如何分工与协作？ <a class="header-anchor" href="#q7-eslint-与-prettier、stylelint-如何分工与协作" aria-label="Permalink to &quot;Q7. ESLint 与 Prettier、Stylelint 如何分工与协作？&quot;">​</a></h3><p><strong>要点</strong>：<strong>ESLint</strong> 管代码质量与潜在错误（含 TS、React/Vue 规则）；<strong>Prettier</strong> 管格式（缩进/引号/换行），不管质量；<strong>Stylelint</strong> 管样式代码规范。三者职责分离，用 <code>eslint-config-prettier</code> 关闭与 Prettier 冲突的规则。</p><p><strong>深度补充</strong>：用 <code>lint-staged</code> + <code>husky</code> 在提交前只检查改动文件（快）；<code>eslint-plugin-import</code> 约束依赖方向，配合 <a href="/frontend-kb-pages/quality/architecture-guard">架构约束</a> 守住分层。Vue/React 各自有官方 eslint 插件。</p><h3 id="q8-ci-cd-在前端项目里通常做什么" tabindex="-1">Q8. CI/CD 在前端项目里通常做什么？ <a class="header-anchor" href="#q8-ci-cd-在前端项目里通常做什么" aria-label="Permalink to &quot;Q8. CI/CD 在前端项目里通常做什么？&quot;">​</a></h3><p><strong>要点</strong>：CI——装依赖、lint、类型检查、单测、构建、E2E；CD——产物上传 CDN、灰度/蓝绿发布、通知。常用 GitHub Actions / GitLab CI。质量门禁是核心：不通过不允许合并。</p><p><strong>深度补充</strong>：缓存 <code>node_modules</code>/<code>.turbo</code> 提速；<code>--filter</code> 只跑受影响包（Monorepo）；发布 npm 用 Changesets + <code>npm publish</code>（含 provenance）。对应 C 级&quot;Docker/K8s/DevOps&quot;（3 份 JD）。</p><h3 id="q9-组件库如何打包与发布" tabindex="-1">Q9. 组件库如何打包与发布？ <a class="header-anchor" href="#q9-组件库如何打包与发布" aria-label="Permalink to &quot;Q9. 组件库如何打包与发布？&quot;">​</a></h3><p><strong>要点</strong>：产物要<strong>多格式</strong>——ESM（<code>es</code>）、CJS（<code>lib</code>）、类型声明（<code>types</code>，<code>vite-plugin-dts</code>）；<code>package.json</code> 的 <code>exports</code> 字段暴露入口；按需加载靠 ESM + tree-shaking 或 <code>unplugin-vue-components</code>/<code>babel-plugin-import</code> 自动导入。</p><p><strong>深度补充</strong>：样式产物单独输出（<code>dist/style.css</code>）或按组件拆分；<code>peerDependencies</code> 声明 React/Vue（避免用户重复引入）；版本遵循 semver；发布前用 <code>npm pack</code> 校验产物。这是 A5 级核心能力（7 份 JD）。</p><h3 id="q10-前端测试体系怎么搭" tabindex="-1">Q10. 前端测试体系怎么搭？ <a class="header-anchor" href="#q10-前端测试体系怎么搭" aria-label="Permalink to &quot;Q10. 前端测试体系怎么搭？&quot;">​</a></h3><p><strong>要点</strong>：<strong>单元</strong>——Vitest/Jest 测工具函数与组件逻辑（<code>@testing-library</code> 测行为不测实现）；<strong>组件</strong>——测试渲染与交互；<strong>E2E</strong>——Playwright 跑真实浏览器关键路径；<strong>覆盖率</strong>做门禁。分层金字塔：单测多、E2E 精。</p><p><strong>深度补充</strong>：<code>@testing-library</code> 的哲学是&quot;像用户一样测试&quot;（查 role/text 而非 class）；Playwright 支持多浏览器、自动等待、录制生成脚本。对应 B2 级（5 份 JD）。AI 提效场景下可作为<strong>质量门禁</strong>卡住 AI 产出。</p><h2 id="二、场景设计题" tabindex="-1">二、场景设计题 <a class="header-anchor" href="#二、场景设计题" aria-label="Permalink to &quot;二、场景设计题&quot;">​</a></h2><blockquote><p>场景题的答题骨架：<strong>澄清需求 → 拆解模块 → 技术选型 → 关键难点 → 边界与权衡 → 效果度量</strong>。先问清约束（规模、兼容、团队），再给方案。</p></blockquote><h3 id="q11-如何设计一个组件库" tabindex="-1">Q11. 如何设计一个组件库？ <a class="header-anchor" href="#q11-如何设计一个组件库" aria-label="Permalink to &quot;Q11. 如何设计一个组件库？&quot;">​</a></h3><p><strong>框架</strong>：需求（给谁用、覆盖哪些端）→ 分层（tokens → 基础组件 → 业务组件）→ 技术（TS、多格式打包、文档站）→ 质量（单测、a11y、视觉回归）→ 交付（semver、按需加载、主题）。</p><p><strong>要点</strong>：</p><ol><li><strong>设计令牌层</strong>：颜色/字号/间距 token 化，支持主题切换（CSS 变量）。</li><li><strong>组件层</strong>：受控 + 非受控双模式；命名与 API 一致（如统一 <code>onChange</code> 签名）。</li><li><strong>样式方案</strong>：CSS Modules / CSS-in-JS / 原子化，权衡可维护性与运行时成本。</li><li><strong>文档与示例</strong>：用 Storybook/VitePress 做文档站（4 份 JD 要求技术文档能力）。</li><li><strong>发布</strong>：多格式产物 + <code>exports</code> + 按需加载 + Changesets 版本管理。</li></ol><p><strong>深度补充</strong>：你做过<strong>双栈同构组件库</strong>——同一套设计 token 与交互契约在 React/Vue 落地，这正是 7 份 JD 要的&quot;组件库/SDK 交付&quot;。讲清&quot;同构&quot;如何降低维护成本、API 如何对齐。</p><h3 id="q12-如何设计一个前端请求层" tabindex="-1">Q12. 如何设计一个前端请求层？ <a class="header-anchor" href="#q12-如何设计一个前端请求层" aria-label="Permalink to &quot;Q12. 如何设计一个前端请求层？&quot;">​</a></h3><p><strong>框架</strong>：实例封装 → 拦截器 → 错误模型 → 取消/重试 → 并发与缓存 → 类型安全。</p><p><strong>要点</strong>：</p><ol><li><strong>实例</strong>：<code>baseURL</code>、超时、默认头，支持多实例（不同网关）。</li><li><strong>拦截器</strong>：请求注入 token/追踪 ID；响应统一处理业务码与非 2xx。</li><li><strong>错误模型</strong>：区分网络错误、超时、HTTP 错误、业务错误，暴露结构化错误。</li><li><strong>取消</strong>：<code>AbortController</code>（组件卸载取消）；<strong>重试</strong>：指数退避 + 幂等方法白名单。</li><li><strong>并发</strong>：<code>Promise.allSettled</code>、并发池；<strong>缓存</strong>：GET 合理缓存（可配 SWR）。</li></ol><p><strong>深度补充</strong>：401 刷新 token 的<strong>并发排队</strong>是关键难点——刷新期间挂起其他请求，刷新完成统一重放，失败则登出并跳转。详见 <a href="/frontend-kb-pages/network/http-layer">HTTP 与请求层设计</a>。</p><h3 id="q13-如何设计-rbac-权限系统与动态路由" tabindex="-1">Q13. 如何设计 RBAC 权限系统与动态路由？ <a class="header-anchor" href="#q13-如何设计-rbac-权限系统与动态路由" aria-label="Permalink to &quot;Q13. 如何设计 RBAC 权限系统与动态路由？&quot;">​</a></h3><p><strong>框架</strong>：角色模型 → 权限粒度 → 路由/菜单生成 → 按钮级控制 → 数据权限。</p><p><strong>要点</strong>：</p><ol><li><strong>模型</strong>：用户 → 角色（Role）→ 权限码（Permission），后端返回权限码列表。</li><li><strong>粒度</strong>：菜单级、按钮级（<code>v-permission</code> / <code>&lt;Can&gt;</code>）、接口级（后端校验）。</li><li><strong>动态路由</strong>：登录后拉权限，前端按权限<strong>过滤/追加</strong>路由表（<code>router.addRoute</code>），并处理 404 兜底。</li><li><strong>按钮控制</strong>：用指令/组件包裹按权限码显隐（<strong>前端控制是体验，安全必须后端兜底</strong>）。</li></ol><p><strong>深度补充</strong>：B 端中后台（6 份 JD）高频。要强调&quot;前端权限只为体验，真正安全由后端强制&quot;。动态路由需处理首次刷新时权限还未加载的路由守卫等待。</p><h3 id="q14-如何实现虚拟滚动" tabindex="-1">Q14. 如何实现虚拟滚动？ <a class="header-anchor" href="#q14-如何实现虚拟滚动" aria-label="Permalink to &quot;Q14. 如何实现虚拟滚动？&quot;">​</a></h3><p><strong>框架</strong>：只渲染可视区 → 容器高度撑起 → 滚动偏移定位。</p><p><strong>要点</strong>：</p><ol><li><strong>固定高度</strong>：总高 = 项数 × 项高；渲染 <code>[start, end]</code> 区间项，用 <code>translateY</code> 偏移。</li><li><strong>动态高度</strong>：需预估 + 实测修正（测量已渲染项高、维护偏移表），复杂度高。</li><li><strong>缓冲</strong>：可视区上下各多渲染几项，减少滚动白屏。</li><li><strong>优化</strong>：<code>will-change</code>、避免滚动中重排、<code>requestAnimationFrame</code> 节流。</li></ol><p><strong>深度补充</strong>：大屏/日志/大表格场景必备（命中 #7 大屏、#1 监控列表）。可用 <code>vue-virtual-scroller</code>、<code>@tanstack/virtual</code>。对比&quot;虚拟列表 vs 分页&quot;的适用边界。</p><h3 id="q15-如何设计大屏适配方案" tabindex="-1">Q15. 如何设计大屏适配方案？ <a class="header-anchor" href="#q15-如何设计大屏适配方案" aria-label="Permalink to &quot;Q15. 如何设计大屏适配方案？&quot;">​</a></h3><p><strong>框架</strong>：设计稿基准 → 缩放策略 → 图表自适应 → 性能。</p><p><strong>要点</strong>：</p><ol><li><strong>缩放</strong>：以固定设计稿宽（如 1920）为基准，用 <code>transform: scale</code> 或 <code>vw/vh</code> 等比缩放；<code>rem</code> + <code>flexible</code> 是移动端方案（大屏一般用 scale）。</li><li><strong>图表自适应</strong>：ECharts 监听 <code>resize</code>；容器尺寸变化用 <code>ResizeObserver</code> 而非 <code>window.resize</code>。</li><li><strong>性能</strong>：大数据量图表降采样、关闭动画、虚拟化表格、Web Worker 计算。</li><li><strong>层级</strong>：背景图/装饰图/数据层分组，避免重排。</li></ol><p><strong>深度补充</strong>：<code>transform: scale</code> 会有模糊与点击坐标偏移问题，需按缩放比换算；<code>ResizeObserver</code> 是容器级自适应的正解。对应 B3 级可视化（5 份）。详见 <a href="/frontend-kb-pages/performance/big-screen">大屏性能</a>。</p><h3 id="q16-如何治理组件-re-render-react-vue" tabindex="-1">Q16. 如何治理组件 re-render（React/Vue）？ <a class="header-anchor" href="#q16-如何治理组件-re-render-react-vue" aria-label="Permalink to &quot;Q16. 如何治理组件 re-render（React/Vue）？&quot;">​</a></h3><p><strong>框架</strong>：定位 → 分层优化 → 度量。</p><p><strong>要点</strong>：</p><ol><li><strong>定位</strong>：先用 Profiler（React DevTools）/ Vue Devtools 找热点，<strong>不要盲目 memo</strong>。</li><li><strong>React</strong>：<code>memo</code> + <code>useMemo/useCallback</code> 稳定 props；状态下移/拆分；<code>children</code> 透传；Context 拆分或换可订阅状态库；列表虚拟化。</li><li><strong>Vue</strong>：<code>v-once</code>、<code>v-memo</code>、<code>shallowRef</code>、<code>computed</code> 缓存、稳定 <code>key</code>。</li><li><strong>度量</strong>：渲染次数统计、<code>why-did-you-render</code>、火焰图。</li></ol><p><strong>深度补充</strong>：强调&quot;<strong>先测量再优化</strong>&quot;，否则 memo 的比较成本可能反噬。层级化的思路（组件级 → 值级 → 结构级）能体现系统性。</p><h3 id="q17-如何做离线消息补偿-im" tabindex="-1">Q17. 如何做离线消息补偿（IM）？ <a class="header-anchor" href="#q17-如何做离线消息补偿-im" aria-label="Permalink to &quot;Q17. 如何做离线消息补偿（IM）？&quot;">​</a></h3><p><strong>框架</strong>：本地存储 → 序号同步 → 增量拉取 → 去重与合并。</p><p><strong>要点</strong>：</p><ol><li><strong>本地存储</strong>：会话与消息存 IndexedDB（异步、大容量）。</li><li><strong>序号</strong>：每条消息有唯一 ID 与全局/会话内<strong>递增序号</strong>（<code>seq</code>）。</li><li><strong>补偿</strong>：重连成功后带 <code>lastSeq</code> 请求 <code>sync</code>，服务端返回缺失消息；实时消息与补偿消息按 <code>seq</code> <strong>去重 + 排序</strong>合并。</li><li><strong>兜底</strong>：断线指数退避重连、心跳保活、乐观发送失败回滚。</li></ol><p><strong>深度补充</strong>：这是 #8 鹏开信息 IM 岗的核心（见 <a href="/frontend-kb-pages/network/im">IM 前端</a>）。要点是&quot;<strong>消息不重不漏</strong>&quot;——靠单调序号 + 客户端幂等去重实现。</p><h3 id="q18-如何搭建前端监控-可观测-体系" tabindex="-1">Q18. 如何搭建前端监控（可观测）体系？ <a class="header-anchor" href="#q18-如何搭建前端监控-可观测-体系" aria-label="Permalink to &quot;Q18. 如何搭建前端监控（可观测）体系？&quot;">​</a></h3><p><strong>框架</strong>：采集 → 上报 → 存储 → 分析告警。</p><p><strong>要点</strong>：</p><ol><li><strong>采集</strong>：<code>onerror</code>/<code>unhandledrejection</code>（异常）、资源错误、接口错误、性能指标（<code>PerformanceObserver</code>）、白屏检测、用户行为埋点。</li><li><strong>上报</strong>：<code>sendBeacon</code> 可靠上报；采样降量；去重合并；携带用户/设备/版本上下文；sourcemap 还原堆栈。</li><li><strong>存储与分析</strong>：聚合看板（错误率、P95 耗时）、告警规则（阈值/突增）。</li><li><strong>SDK 设计</strong>：可插拔插件、体积控制、错误隔离（<code>try/catch</code> 包裹，不影响宿主）。</li></ol><p><strong>深度补充</strong>：这是 #3 腾讯外包&quot;监控 SDK/可观测体系&quot;核心考点。要讲清&quot;SDK 自身不能拖垮业务&quot;——异步上报、异常隔离、体积预算。也呼应 A5 级 SDK 交付能力。</p><h2 id="面试要点" tabindex="-1">面试要点 <a class="header-anchor" href="#面试要点" aria-label="Permalink to &quot;面试要点&quot;">​</a></h2><ol><li><strong>Vite vs Webpack？</strong> 开发基于原生 ESM（无打包、极快 HMR），生产 Rollup 打包；Webpack 先打包再启动。</li><li><strong>pnpm 优势？</strong> 内容寻址 + 硬链接省空间，严格 node_modules 杜绝幽灵依赖。</li><li><strong>Monorepo 工具链？</strong> pnpm workspace 组织 + Turborepo 任务编排缓存 + Changesets 版本发布。</li><li><strong>组件库交付？</strong> 多格式产物（ESM/CJS/types）+ <code>exports</code>/peerDeps + 按需加载 + semver + 文档站。</li><li><strong>场景题骨架？</strong> 澄清需求 → 拆模块 → 选型 → 难点 → 权衡 → 度量，先问清约束再给方案。</li><li><strong>RBAC 要点？</strong> 角色-权限码模型 + 动态路由过滤 + 按钮级控制；前端只为体验，安全靠后端。</li><li><strong>虚拟滚动本质？</strong> 只渲染可视区 + 容器撑高 + 偏移定位；动态高度需实测修正。</li><li><strong>监控 SDK 关键？</strong> 可靠上报（sendBeacon）+ 异常隔离 + 采样 + sourcemap 还原。</li></ol>',78)])])}const h=e(s,[["render",a]]);export{u as __pageData,h as default};
